// Types for data/index.json and data/part-*.json (generated by tools/build.py).
// Display conventions: scale degrees use a caret (1̂ … 7̂); Roman numerals use ° (diminished), ø (half-diminished),
// + (augmented), Δ (major 7th). Figures in labels are written with a slash: V6/5, I6/4, V4/2.

export type PartId = 'p1' | 'p2' | 'p3' | 'p5' | 'p6';   // follows the owner's notes (there is no Part IV in the notes)
export type VerificationStatus = 'verified' | 'partly' | 'notes-only' | 'flagged';
export type TopicKind = 'concept' | 'table' | 'procedure' | 'progression' | 'checklist' | 'form';
export type CheckLevel = 'white' | 'blue' | 'green' | 'yellow' | 'orange' | 'red';  // notes p.20, least → most problematic
export type CheckType =
  | 'range' | 'leap' | 'doubling' | 'contrary' | 'hidden' | 'augLeap' | 'overlap' | 'crossing'
  | 'viiRoot' | 'sixFour' | 'doubledLT' | 'spacing' | 'seventh' | 'seventhLeap' | 'leadingTone'
  | 'unequal5' | 'aug6' | 'parallel' | 'bigLeap' | 'tie';

// ---------------------------------------------------------------- index.json
export interface IndexFile {
  version: 1;
  parts: Part[];
  chapters: Chapter[];
  lessons: Lesson[];          // Dr. B video lessons 1–47
  tools: ToolSpec[];          // interactive tools to build (ids referenced by Topic.tools)
  checks: { type: CheckType; level: CheckLevel; label: string }[];
  ranges: {
    note: string;
    S: VoiceRange; A: VoiceRange; T: VoiceRange; B: VoiceRange;
    spacing: { 'S-A': string; 'A-T': string; 'T-B': string };
  };
}
export interface VoiceRange { low: string; high: string; extLow?: string; extHigh?: string }

export interface Part { id: PartId; num: string; title: string; notesPages: string }

export interface Chapter {
  id: string;           // 'ch0' … 'ch22' (numbers follow the notes)
  part: PartId;
  num: number;
  title: string;
  notesPages: string;
  video: number[];      // Lesson.num values
  textbook: string;     // Aldwell/Schachter/Cadwallader 5e units used for cross-checking
}

export interface Lesson {
  num: number;
  title: string | null;
  url: string | null;   // YouTube watch URL when confirmed
  chapters: string[];   // Chapter ids
  note?: string;
}

export interface ToolSpec { id: string; title: string; chapters: string[]; spec: string }

// ---------------------------------------------------------------- part-*.json
export interface PartFile {
  version: 1;
  part: Part;
  chapters: Chapter[];
  topics: Topic[];
}

export interface Topic {
  id: string;                   // stable slug, use in URLs (#id); unique across all parts
  part: PartId;
  chapter: string;              // Chapter.id
  title: string;
  kind: TopicKind;
  summary: string;
  terms?: { term: string; def: string }[];
  rules?: string[];             // HARD rules → red "Rule" badge
  guidelines?: string[];        // SOFT rules / advice → amber "Guideline" badge
  tables?: Table[];
  examples?: Example[];
  tools?: string[];             // ToolSpec ids
  seeAlso?: string[];           // Topic ids (may be in another part file)
  sources: { notes?: string; textbook?: string; textbook2?: string; video?: number[]; web?: string[] };  // textbook = Aldwell/Schachter 5e, textbook2 = Burstein & Straus 2e
  verification: { status: VerificationStatus; checks: string[]; flags?: string[] };
}

export interface Table {
  id: string;
  title: string;
  columns: string[];
  rows: string[][];
  note?: string;
  highlight?: [number, number][];
}

export interface Example {
  id: string;
  title: string;
  key: string;                  // 'C', 'Eb', 'F#' = major; 'a', 'c', 'f#' = minor
  meter: string;                // e.g. '4/4'
  beatUnit: 'quarter' | 'half'; // what 1.0 beat means in t/d
  notation: string;             // source of truth (BUILD_BRIEF §4)
  intent: 'model' | 'error' | 'line' | 'demo';
  caption?: string;
  source?: string;              // where the music comes from (notes page / "voiced by the builder")
  expect?: CheckType[];         // intent 'error': the faults this example is meant to show
  allow?: CheckType[];          // checks intentionally switched off for this example (explained in caption/flags)
  parts: number;                // number of voices
  realized: {
    voiceOrder: string;         // "top→bottom; last = bass"
    lengthBeats: number;
    voices: RealizedEvent[][];  // voices[0] = soprano/top … voices[n-1] = bass
    slices: Slice[];            // one per chord (analysis row)
  };
  checker?: CheckIssue[];       // present when the checker found something (always for intent 'error')
}

export interface RealizedEvent {
  t: number;                    // onset in beats
  d: number;                    // duration in beats
  rest?: true;
  pitch?: string;               // scientific pitch: 'F#4', 'Bb3', 'C##5'
  midi?: number;
  tie?: true;                   // tied from the previous event of this voice
  natural?: true;               // print an explicit natural sign
}

export interface Slice {
  t: number; d: number; bar: number;
  label: string | null;         // Roman numeral / analysis, e.g. 'V6/5/ii', 'It+6', 'I=IV' (pivot: old key = new key)
  figures: string;              // computed from the pitches: '5/3', '6/3', '6/4', '7', '6/5', '4/3', '4/2' or raw '9/5/3'
  bassDegree: string | null;    // '1'…'7' with '#', 'b' or 'n' relative to the key signature (minor = natural minor)
  root: string | null;          // chord root letter+accidental when the slice is tertian
}

export interface CheckIssue {
  type: CheckType;
  level: CheckLevel;
  beat: number;
  voices: string | string[] | null;   // 'S' | ['S','B'] …
  detail: string;
}

/* ---------- data/history-background.json (added from the History page source) ---------- */
// Technical content from The Cambridge History of Western Music Theory (ed. Christensen, 2002) that overlaps this tab.
// The History tab keeps the narrative; this tab now owns the rules, tools and technical quiz items.
export interface HistoryBackgroundFile {
  version: 1; pack: string;
  from: { source: 'cht'; title: string; editor: string; year: number };
  historyTab: 'history';                         // route of the History tab, for "Read the history →" links
  topics: BackgroundTopic[];
  tools: BackgroundTool[];
}
export interface BackgroundTopic {
  id: string; title: string;
  attachTo: { ref: string; note: string };      // an id in THIS pack (chapter / group / topic / tab) where the topic is shown
  historyArticles: string[];                     // History-tab article ids: link "Read the history →"
  points: string[];                              // may contain <i>, <b>
  rules: { text: string; who: string }[];        // Rule badge (precept stated by the named historical writer)
  guidelines: { text: string; who: string }[];   // Guideline badge
  terms: { term: string; def: string }[];
  tools: string[];                               // ids in tools[]
  quiz: { id: string; q: string; options: string[]; answer: number; why: string }[];
  sourceRefs: { source: 'cht'; chapter: number; pages: string; author: string; historyArticle: string }[];
}
export interface BackgroundTool {
  id: string; title: string; spec: string; tests: string[];
  extends: string | null;                        // id of an existing tool in this pack to extend instead of adding a new one
  reference: string;                             // working implementation: tools/history-tools.js → function()
}
